# ---- 00_base.py ----
"""Base: constants, trace lines, fuel, error capture (docs/design/CORE.md).

Trace format (tools/plog.py): P|round|team|champ|tag|text, team A or B, champ = int(ChampionType).
Never import traceback (froze champions ~136 rounds [measured A17]) or json (~35 rounds [measured A29]).
"""
import cambc
from cambc import game_map, vision

V = cambc.Vec2
Bitboard = cambc.Bitboard
DistanceField = cambc.DistanceField
Team = cambc.Team
fuel = cambc.fuel_remaining

TRACE = 1                   # 0: no trace lines at all (ladder submissions)
FUEL_BUDGET = 2_500_000     # per play turn, Python [measured A16]; the first play turn has ~4.6M [measured]
RESERVE = 400_000           # fuel never spent on background work (fields) [provisional, tzu's value]
FAR = 65535                 # "unreachable" in every distance we hand out (field max_distance) [sdk]
DIRS = (V.NORTH, V.NORTH_EAST, V.EAST, V.SOUTH_EAST, V.SOUTH, V.SOUTH_WEST, V.WEST, V.NORTH_WEST)

# ChampionState bits [sdk __init__.py]: read me.state() once per turn and test bits.
ST_ALIVE = 1
ST_RECALLING = 2
ST_SUBMITTING = 4
ST_CAN_MOVE = 8
ST_CAN_ATTACK = 16

_TAG = ["?|draft"]          # "team|champ", set by base_init() on the first play turn


def base_init():
    """Team letter and champion id, once. cambc._bc.my_team() is the absolute team (0 = A) [sdk]."""
    _TAG[0] = f"{'AB'[cambc._bc.my_team()]}|{int(cambc.me().champion_name())}"


def trace(tag, text):
    if TRACE:
        print(f"P|{cambc.round_number()}|{_TAG[0]}|{tag}|{text}", flush=True)


def err_text(error):
    """err:<line>:<type>:<msg>, line of the innermost frame, walked from __traceback__ (no traceback module)."""
    tb, line = error.__traceback__, 0
    while tb is not None:
        line, tb = tb.tb_lineno, tb.tb_next
    msg = str(error).replace(" ", "_").replace("|", "/")[:60]
    return f"err:{line}:{type(error).__name__}:{msg}"


class Fuel:
    """Per-turn fuel accounting: start() at the top of the turn, used() any time after."""
    __slots__ = ("f0",)

    def __init__(self):
        self.f0 = 0

    def start(self):
        self.f0 = fuel()

    def used(self):
        return self.f0 - fuel()


FUEL = Fuel()


def spent(f1, r1):
    """Fuel spent since fuel() read f1 in round r1, also across a turn boundary (an overrun: the turn went on in
    the next round, which started at FUEL_BUDGET)."""
    f = fuel()
    return f1 - f if cambc.round_number() == r1 else f1 + FUEL_BUDGET - f


def cheb(a, b):
    return max(abs(a.x - b.x), abs(a.y - b.y))

# ---- 20_world.py ----
"""World: map cache, camp table, distance fields, per-turn snapshot (CORE.md). Trimmed from tzu's 20_world.

Field keys: "spawn" (our spawn), "espawn" (enemy spawn region), "a<i>" (altar i's tribute ring, i = row-major
index in game_map.altars().positions() [sdk]), "g<h>" (stand next to a camp of group h, h = int(CampGroup)).
w.dist(key, pos) is None while the field is not computed yet, FAR when unreachable.
Fuel [measured 13 Oct, tzu]: camp_groups() ~0.74-1M (ONCE), a field ~280k at 80x80, field.get ~2.3k,
vision.champions(team) ~17k, camp.health() ~3k, CampGroup.state() ~27k.
"""

SNAP_RANGE = 4      # read camp HP only for groups within this of us (+ the target group)
AWAKE_ROUNDS = 2    # a camp sleeps 2 rounds after nobody is in range [measured A32]
HP_STALE = 40       # last-known camp HP is trusted this many rounds: no regen [measured A28]
CAMP_RANGE = 3      # every monster's attack range [measured A31]
CAMP_STR = (20, 60, 0, 0, 200)   # Strength by CampType WOLF, ELK, GEM, GOLD, MONOLITH [rules]
CONTEST_X = 1.3     # bank altar contested iff d(espawn, altar) <= CONTEST_X * d(spawn, altar) (CORE.md -> Modes)
BG_MARGIN = 100_000         # background leaves room for the trace line after it
JOB_CAP = 1_200_000         # no job estimate above this: the queue must never stall behind one job
INDEX_FUEL = 1_000_000      # boot step "index" (the one camp_groups() call) [measured ~0.74-1M]


def fget(field, pos):
    """Field value at pos; FAR when unreached, off the map or a wall."""
    try:
        v = field.get(pos)
    except Exception:
        return FAR
    return v if 0 <= v < FAR else FAR


def disk(center, r):
    b = Bitboard()
    b.draw_chebyshev(center, r)
    return b


class Snap:
    """What this champion knows this turn. Filled by World.snapshot()."""
    __slots__ = ("rnd", "st", "alive", "can_move", "can_attack", "submitting", "recalling", "stunned",
                 "pos", "hp", "max_hp", "bag", "gold", "enemies", "allies", "camp_hp", "near", "near_t",
                 "awake", "cost", "_occ")

    def occupied(self):
        """Tiles of visible champions plus teleport reservations (not walkable) [sdk]. Read lazily."""
        if self._occ is None:
            self._occ = vision.champion_tiles() | vision.teleport_tiles()
        return self._occ


class World:
    def __init__(self):
        """Cheap part only; setup() does the expensive boot steps."""
        self.me = me = cambc.me()
        self.ctype = int(me.champion_name())
        self.W, self.H = game_map.width(), game_map.height()
        self.spawn = game_map.spawn_region(Team.ALLY)          # Bitboard
        self.espawn_bb = game_map.spawn_region(Team.ENEMY)     # Bitboard
        self.espawn = self.espawn_bb.positions()               # list of enemy spawn tiles
        self.altar_pos = game_map.altars().positions()
        self.last_pos = me.position()
        self.snap = None
        self.groups = {}       # handle -> CampGroup
        self.camps = {}        # handle -> tuple of Camp
        self.anchor = {}       # key (and int h) -> one tile of the goal's object (greedy fallback)
        self.fields, self.goals, self.queue = {}, {}, []      # field key -> DistanceField / goal Bitboard; bg queue
        self.blocked = self.free = self.tile_group = self.camp_tiles = None
        self.scratch = Bitboard()
        self.est = {"field": self.W * self.H * 60 + 40_000, "_blk": 400_000, "_tiles": 1_000_000}
        self.last_hp, self.last_hp_r, self.awake_until = {}, {}, {}
        self.my_hp = 0.0         # my HP last turn (a drop with no enemy in sight: a camp hits me)
        self.bank_altar = None   # altar index nearest our spawn by field
        self.contested = False   # CORE.md -> Modes
        self.boot = ["index", "_blk", "_tiles", "spawn", "espawn", "modes"]
        self.ready = False

    def setup(self):
        """Boot steps in order, as many as fit above RESERVE (always at least one per call). True when ready."""
        ran = False
        while self.boot:
            k = self.boot[0]
            need = INDEX_FUEL if k == "index" else (50_000 if k == "modes" else self.cost_of(k))
            if ran and fuel() - RESERVE < need:
                break
            self.index() if k == "index" else self.modes() if k == "modes" else self.run(k)
            self.boot.pop(0)
            ran = True
        self.ready = not self.boot
        return self.ready

    def index(self):
        for g in game_map.camp_groups():           # the ONLY camp_groups() call (~0.74M)
            h = int(g)
            self.groups[h] = g
            cs = self.camps[h] = g.camps()
            self.anchor[h] = self.anchor[f"g{h}"] = cs[0].spawn_position()
        self.anchor["spawn"] = self.spawn.positions()[0]
        self.anchor["espawn"] = self.espawn[0]
        for i, a in enumerate(self.altar_pos):
            self.anchor[f"a{i}"] = a

    def ring_min(self, key, i):
        """Field key's smallest value on altar i's tribute ring (FAR if none)."""
        f = self.fields.get(key)
        return FAR if f is None else min((fget(f, p) for p in self.goal(f"a{i}").positions()), default=FAR)

    def modes(self):
        """Bank altar, contested flag, then the background queue: altars, groups nearest-first."""
        n = len(self.altar_pos)
        ds = [self.ring_min("spawn", i) for i in range(n)]
        if n:
            sp = self.anchor["spawn"]
            b = min(range(n), key=lambda i: (ds[i], sp.chebyshev_distance(self.altar_pos[i])))
            self.bank_altar = b
            self.contested = ds[b] < FAR and self.ring_min("espawn", b) <= CONTEST_X * ds[b]
        pos = self.last_pos
        alt = sorted(range(n), key=lambda i: ds[i])
        grp = sorted(self.groups, key=lambda h: pos.chebyshev_distance(self.anchor[h]))
        self.queue = [f"a{i}" for i in alt] + [f"g{h}" for h in grp]

    def job_blk(self):
        """Blocked mask: walls, holes, altars, the enemy spawn [sdk], camp spawn tiles (never routed over)."""
        ct = Bitboard()
        for g in self.groups.values():
            ct |= g.spawn_tiles()
        self.camp_tiles = ct
        self.blocked = game_map.walls() | game_map.holes() | game_map.altars() | self.espawn_bb | ct
        self.free = ~self.blocked

    def goal(self, key):
        """The goal bitboard of a field key, built on first use (needs "_blk")."""
        b = self.goals.get(key)
        if b is not None:
            return b
        free = self.free
        if key == "spawn":
            b = self.spawn & free
        elif key == "espawn":
            b = self.espawn_bb
        elif key[0] == "a":
            b = disk(self.altar_pos[int(key[1:])], cambc.constants.SUBMIT_GEMS_RANGE) & free
        else:                                          # "g<h>": stand next to a camp of the group
            b = Bitboard()
            for c in self.camps[int(key[1:])]:
                b.draw_chebyshev(c.spawn_position(), 1)
            b &= free
        self.goals[key] = b
        return b

    def run(self, key):
        """Run one job now (index job or field); self-correct its kind's estimate."""
        kind = key if key in ("_blk", "_tiles") else "field"
        if kind == "field" and self.blocked is None:
            self.run("_blk")
        f0, r0 = fuel(), cambc.round_number()
        if kind == "_blk":
            self.job_blk()
        elif kind == "_tiles":
            self.tile_group = {c.spawn_position(): h for h, cs in self.camps.items() for c in cs}
        else:
            roots = self.goal(key)
            f = DistanceField()
            f.compute(self.blocked & ~roots, roots, self.scratch, FAR)
            self.fields[key] = f
        cost = spent(f0, r0)
        self.queue = [k for k in self.queue if k != key]
        est, target = self.est[kind], int(cost * 1.3)
        self.est[kind] = target if target > est else (3 * est + target) // 4
        return cost

    def cost_of(self, key):
        k = key if key in ("_blk", "_tiles") else "field"
        c = self.est[k] + (self.est["_blk"] if k == "field" and self.blocked is None else 0)
        return min(c, JOB_CAP)

    def ensure(self, key):
        """Compute key's field now if it is missing and fits the turn under the reserve."""
        if key not in self.fields and fuel() - RESERVE > self.cost_of(key):
            self.run(key)
        return key in self.fields

    def want(self, key):
        """Move key's field to the front of the background queue."""
        if key not in self.fields:
            self.queue = [key] + [k for k in self.queue if k != key]

    def work(self):
        """Background: fields until the next one might not fit. Returns (jobs, fuel)."""
        n, f0 = 0, fuel()
        while self.queue and fuel() - RESERVE - BG_MARGIN > self.cost_of(self.queue[0]):
            self.run(self.queue[0])
            n += 1
        return n, f0 - fuel()

    def dist(self, key, pos):
        """Walking distance from pos to key's goal tiles; None while not computed, FAR when unreachable."""
        f = self.fields.get(key)
        return None if f is None else fget(f, pos)

    def near(self, pos, r):
        """[(spawn tile, group handle)] of camps within Chebyshev r of pos."""
        if self.tile_group is None:
            return []
        b = disk(pos, r)
        b &= self.camp_tiles
        tg = self.tile_group
        return [] if b.is_empty() else [(p, tg[p]) for p in b.positions()]

    def snapshot(self, rnd, target=None):
        """One state() read; champions in vision; camp HP only for groups within SNAP_RANGE + the target."""
        f0 = fuel()
        self.snap = s = Snap()
        s.rnd, s._occ = rnd, None
        s.enemies, s.allies, s.camp_hp, s.awake = [], [], {}, set()
        me = self.me
        s.st = st = int(me.state())
        s.alive = bool(st & ST_ALIVE)
        s.recalling = bool(st & ST_RECALLING)
        s.submitting = bool(st & ST_SUBMITTING)
        s.can_move = bool(st & ST_CAN_MOVE)
        s.can_attack = bool(st & ST_CAN_ATTACK)
        try:
            s.gold = me.gold_count()                   # dead too: rule 0 shops [unverified whether it raises]
        except Exception:
            s.gold = 0
        if not s.alive:
            s.pos, s.near, s.near_t, s.stunned, s.hp, s.max_hp, s.bag = self.last_pos, set(), [], False, 0.0, 0.0, 0
            s.cost = f0 - fuel()
            return s
        s.pos = pos = me.position()
        self.last_pos = pos
        s.hp, s.max_hp, s.bag, s.stunned = me.health(), me.max_health(), me.gem_count(), False
        if not s.can_move and not s.recalling and not s.submitting:
            try:
                s.stunned = me.buffs().has_stun()
            except Exception:
                pass
        for c in vision.champions(Team.ENEMY):       # visible only [sdk]: no read raises
            s.enemies.append((c.position(), c.health(), c.gem_count(), c))
        for c in vision.champions(Team.ALLY):
            p = c.position()
            if p != pos:                              # not me
                s.allies.append((p, c.health(), c.gem_count(), c))
        hurt = s.hp < self.my_hp and not s.enemies     # hit with no enemy in sight: a camp in range hits me
        self.my_hp = s.hp
        s.near_t = nt = self.near(pos, SNAP_RANGE)
        s.near = hs = {h for _, h in nt}
        if isinstance(target, int) and target in self.camps:
            hs = hs | {target}
        for h in hs:
            row = []
            for c in self.camps[h]:
                if not c.is_visible():               # dead or out of vision: health() would raise [sdk]
                    row.append(None)
                    continue
                hp = c.health()
                k = int(c)
                old = self.last_hp.get(k)
                if old is not None and hp < old:      # took damage: awake (no engine flag [sdk])
                    self.awake_until[h] = rnd + AWAKE_ROUNDS
                self.last_hp[k] = hp
                self.last_hp_r[k] = rnd
                row.append(hp)
            s.camp_hp[h] = row
            if self.awake_until.get(h, -1) >= rnd - 1 or hurt:
                self.keep_awake(h, row, pos, rnd)
            if self.awake_until.get(h, -1) >= rnd:
                s.awake.add(h)
        s.cost = f0 - fuel()
        return s

    def keep_awake(self, h, row, pos, rnd):
        """A group sleeps only after AWAKE_ROUNDS with no champion in range [rules, measured A32]: an awake group
        (or one hitting me) with a live monster within CAMP_RANGE of me stays awake although its HP is not
        dropping (nobody hits it while I step out or recall: damage would cancel the recall [rules])."""
        for c, hp in zip(self.camps[h], row):
            if hp and c.spawn_position().chebyshev_distance(pos) <= CAMP_RANGE:
                self.awake_until[h] = rnd + AWAKE_ROUNDS
                return

    def hp_known(self, camp, mx, rnd):
        """Last-known HP of a camp not read this turn, else mx (no regen [measured A28]; stale after HP_STALE)."""
        k = int(camp)
        r = self.last_hp_r.get(k)
        return mx if r is None or rnd - r > HP_STALE else self.last_hp.get(k, mx)

    def gstate(self, h):
        """alive | dead (cleared, reward unclaimed) | respawning | - (unknown). ~27k out of vision."""
        try:
            st = self.groups[h].state()
        except Exception:
            return "-"
        if isinstance(st, game_map.CampGroupRewardAvailable):
            return "dead"
        if isinstance(st, game_map.CampGroupRespawning):
            return "respawning"
        return "alive"


_COMP = {}       # group handle -> rows (cached: static)
_CAMP_HP = {}    # CampType -> base health [sdk base_stats(); works out of vision]


def group_comp(w, h):
    """Rows (kind, max_hp, Str, x, y) of group h's camps, cached."""
    c = _COMP.get(h)
    if c is None:
        out = []
        for camp in w.camps.get(h, ()):
            k = int(camp.kind())
            if k not in _CAMP_HP:
                _CAMP_HP[k] = camp.base_stats().base_health
            p = camp.spawn_position()
            out.append((k, _CAMP_HP[k], CAMP_STR[k], p.x, p.y))
        c = _COMP[h] = tuple(out)
    return c

# ---- 30_nav.py ----
"""Nav: the only code that calls move. Trimmed from bots/tzu/parts/30_nav.py (no detours, no risk masks).

goto(key, rnd) -> 'here' | 'moving' | 'blocked' | 'stuck'
    here      on a goal tile of key
    moving    moved one tile this turn
    blocked   did not move this turn (tile taken, can't move, or the field is not computed and greedy failed)
    stuck     no progress for GIVE_UP_ROUNDS on this key, or no route from here
nav.act holds a short token for the trace line: mv | mv:sd (sidestep) | mv:gr (greedy) | mv:un | wait.
"""

GIVE_UP_ROUNDS = 12     # no progress this long on one key -> "stuck" (the rules pick something else)


class Nav:
    def __init__(self, w):
        self.w = w
        self.key = None
        self.last_r = -9
        self.act = "wait"
        self.moved_round = -1
        self.dest = None        # tile we moved to this round
        self.prev = None        # tile we came from (no sidestep back)

    def start(self, key):
        self.key, self.best, self.since, self.waited = key, FAR, 0, 0

    def move(self, q):
        """The single move call site; one move per turn. False when the engine refuses or raises."""
        s = self.w.snap
        if self.moved_round == s.rnd:
            return False
        try:
            ok = self.w.me.move_absolute(q)
        except Exception:
            return False
        if ok:
            self.prev = s.pos
            self.moved_round = s.rnd
            self.dest = q
        return ok

    def goto(self, key, rnd):
        """One step along key's field (computed now if it fits, else greedy towards its anchor)."""
        w, s = self.w, self.w.snap
        if key != self.key or rnd - self.last_r > 1:
            self.start(key)            # a new trip (other key, or a gap: death, recall, a fight) resets progress
        self.last_r = rnd
        if self.moved_round == rnd:
            return "moving"
        pos = s.pos
        field = w.fields.get(key)
        if field is None and w.ensure(key):
            field = w.fields[key]
        if field is None:
            w.want(key)
            return self.greedy(w.anchor.get(key))
        d = fget(field, pos)
        if d == 0:
            self.act = "wait"
            return "here"
        if d >= FAR:
            return self.unstick(field)
        if d < self.best:
            self.best, self.since = d, 0
        elif s.can_move:
            self.since += 1
        if self.since >= GIVE_UP_ROUNDS:
            self.act = "wait"
            return "stuck"
        if not s.can_move:
            self.act = "wait"
            return "blocked"
        av = self.awake_mask(key)
        try:
            step = field.next_move_from(pos)
        except Exception:
            step = None
        if step is not None and not (av is not None and av.is_set(pos + step) and not av.is_set(pos)):
            if self.move(pos + step):
                self.waited, self.act = 0, "mv"
                return "moving"
        # Slow path: the best tile is taken (or enters an awake camp's range). Another strictly downhill tile,
        # else wait one round, else a sideways tile, else (awake range only) the field step anyway.
        here = d
        occ = s.occupied()
        down, side = [], []
        for dv in DIRS:
            q = pos + dv
            v = fget(field, q)
            if v >= FAR or occ.is_set(q) or (av is not None and av.is_set(q) and not av.is_set(pos)):
                continue
            if v < here:
                down.append((v, q))
            elif v == here and q != self.prev:
                side.append((v, q))
        down.sort(key=lambda t: t[0])
        for v, q in down:
            if self.move(q):
                self.waited, self.act = 0, "mv"
                return "moving"
        if self.waited < 1:           # whoever is in the way usually moves on next round
            self.waited += 1
            self.act = "wait"
            return "blocked"
        for v, q in side:
            if self.move(q):
                self.waited, self.act = 0, "mv:sd"
                return "moving"
        if step is not None and self.move(pos + step):    # only an awake range was in the way: go anyway
            self.waited, self.act = 0, "mv"
            return "moving"
        self.act = "wait"
        return "blocked"

    def unstick(self, field):
        """Our tile is a wall of the field (a camp spawn tile, the enemy spawn) or the goal is unreachable:
        step to the neighbour with the lowest finite value."""
        s = self.w.snap
        if not s.can_move:
            self.act = "wait"
            return "blocked"
        pos = s.pos
        for v, q in sorted(((fget(field, pos + dv), pos + dv) for dv in DIRS), key=lambda t: t[0]):
            if v >= FAR:
                break
            if self.move(q):
                self.act = "mv:un"
                return "moving"
        self.since += 1
        self.act = "wait"
        if self.since >= GIVE_UP_ROUNDS or all(fget(field, pos + dv) >= FAR for dv in DIRS):
            return "stuck"
        return "blocked"

    def awake_mask(self, key):
        """Tiles within range 3 of a live monster of an awake group other than the goal group, or None."""
        s, w = self.w.snap, self.w
        m = None
        for h in s.awake:
            if key == f"g{h}":
                continue
            for c, hp in zip(w.camps[h], s.camp_hp.get(h) or ()):
                if hp:
                    if m is None:
                        m = Bitboard()
                    m.draw_chebyshev(c.spawn_position(), CAMP_RANGE)
        return m

    def greedy(self, goal, sideways=False):
        """No field yet: a Chebyshev step towards a goal tile (with sideways, an equal-distance tile too)."""
        s = self.w.snap
        if goal is None or not s.can_move:
            self.act = "wait"
            return "blocked"
        pos = s.pos
        d = goal.chebyshev_distance
        here = d(pos)
        if here == 0:
            self.act = "wait"
            return "here"
        for dv in sorted(DIRS, key=lambda v: d(pos + v)):
            q = pos + dv
            if d(q) > here or (d(q) == here and not sideways):
                break
            if self.move(q):
                self.act = "mv:gr"
                return "moving"
        self.act = "wait"
        return "blocked"

# ---- 40_kit.py ----
"""Kits (docs/design/CORE.md, Kits): the only champion-specific code. Abilities are classified from the
engine's ability kinds (Ability.is_damage / is_aoe_damage / is_cc / is_attack_reset / is_shield [sdk]),
so no slot numbers are hard-coded. No kiting, no dashes, no stun planning in v1: a damage slot is cast
for its damage (Ryth's area stun deals 1x Focus, so it counts), resets give a second basic attack.
"""
import cambc

IT = cambc.ItemType
CT = cambc.ChampionType

# type id -> (base max HP, base Strength, ranged) [rules: GameRules.md, Champion roster]
CHAMP_BASE = {
    0: (1200, 50, False),   # Ryth
    1: (900, 45, True),     # Vesper Vale
    2: (800, 70, False),    # Vendetta
    3: (700, 30, True),     # Cassi
    4: (900, 40, False),    # Issac
    5: (750, 35, True),     # Stellar
    6: (700, 35, True),     # Prism
    7: (1200, 45, False),   # Marcella
    8: (700, 45, True),     # Willow
    9: (900, 40, False),    # Ren
    10: (1000, 50, False),  # Varg
    11: (750, 35, True),    # Tavi
}
# Shard plan (CORE.md rule 0): Strength for the hitters, Health for the tanks. Monster family: +10% damage
# to camps at 5 shards; Durability: -10% incoming damage at 5 shards [rules, Emblem families].
SHOP_PLAN = {
    int(CT.VENDETTA): IT.MONSTER_SHARD_OF_STRENGTH,
    int(CT.VARG): IT.MONSTER_SHARD_OF_STRENGTH,
    int(CT.STELLAR): IT.MONSTER_SHARD_OF_STRENGTH,
    int(CT.RYTH): IT.DURABILITY_SHARD_OF_HEALTH,
    int(CT.MARCELLA): IT.DURABILITY_SHARD_OF_HEALTH,
}
SHARD_GOLD = 30         # gold per shard [rules]
SPELL_RANGE = 4         # every damage spell's cast range [rules, champion kits]

# Kit state, set once by kit_init. dmg: (slot, ground?, excl?, range) of the damage slot or None;
# reset / shield: slot index or -1. cache: per-round my_hit value.
K = {"me": None, "type": -1, "ar": 1, "dmg": None, "reset": -1, "shield": -1, "hit_r": -1, "hit": 0.0}


def kit_init(w, s):
    """Cache my type, attack range and which slot is the damage spell / attack reset / self-shield."""
    me = getattr(w, "me", None) or cambc.me()
    K["me"] = me
    try:
        K["type"] = int(me.champion_name())
        K["ar"] = int(me.attack_range())
    except Exception:
        K["ar"] = 3 if CHAMP_BASE.get(K["type"], (0, 0, False))[2] else 1
    try:
        for a in me.abilities():
            info = a.info()
            if info is None:
                continue
            i = a.slot()
            if a.is_damage() or a.is_aoe_damage() or (a.is_cc() and _dmg_of(a) > 0):
                ground = a.can_target_ground() and not (a.can_target_camps() or a.can_target_enemies())
                rng = int(getattr(info, "range", SPELL_RANGE) or SPELL_RANGE)
                excl = bool(getattr(info, "exclusive_with_movement", False))
                if K["dmg"] is None:
                    K["dmg"] = (i, ground, excl, rng)
            elif a.is_attack_reset():
                K["reset"] = i
            elif a.is_shield() and a.can_target_self():
                K["shield"] = i
    except Exception as e:
        trace("kit", f"init_fail {type(e).__name__}")
    trace("kit", f"type={K['type']} ar={K['ar']} dmg={K['dmg']} reset={K['reset']} shield={K['shield']}")


def _dmg_of(a):
    """The damage one cast of ability a deals now (no target: before mitigation) [sdk damage_amount]."""
    try:
        return float(a.damage_amount())
    except Exception:
        return 0.0


def _slot(i):
    """Ability in slot i of my champion, or None."""
    try:
        return K["me"].abilities()[i]
    except Exception:
        return None


def _ready(i):
    """Slot i is off cooldown and I may cast this turn (is_ready checks can_cast [sdk])."""
    a = _slot(i) if i >= 0 else None
    try:
        return a is not None and a.is_ready()
    except Exception:
        return False


def _dmg_castable():
    """Damage slot ready and castable this turn; an excludes-walking spell needs my walk unspent."""
    d = K["dmg"]
    if d is None or not _ready(d[0]):
        return False
    if d[2]:
        try:
            return K["me"].can_move()
        except Exception:
            return False
    return True


def my_str():
    """My live Strength (shards included) [sdk Champion.strength]."""
    try:
        return float(K["me"].strength())
    except Exception:
        return float(CHAMP_BASE.get(K["type"], (0, 50, False))[1])


def my_hit(w, s):
    """Damage I deal one target this turn: Strength plus the best ready cast (damage spell, or a reset's
    second basic attack). Cached per round."""
    if K["hit_r"] == s.rnd:
        return K["hit"]
    S = my_str()
    extra = 0.0
    if _dmg_castable():
        extra = _dmg_of(_slot(K["dmg"][0]))
    if K["reset"] >= 0 and _ready(K["reset"]):
        extra = max(extra, S)
    K["hit_r"], K["hit"] = s.rnd, S + extra
    return K["hit"]


def hit_range(w):
    """My basic attack range: 1 melee, 3 ranged [rules]."""
    return K["ar"]


def _attack(me, unit):
    """One basic attack; False on any engine refusal."""
    try:
        if not me.can_attack():
            return False
        me.attack(unit)
        return True
    except Exception as e:
        trace("kit", f"atk_fail {type(e).__name__}")
        return False


def _cast_dmg(me, unit, d):
    """Cast the damage slot on unit (or on its tile for a ground spell)."""
    try:
        if me.position().chebyshev_distance(unit.position()) > d[3]:
            return False
        return bool(me.abilities()[d[0]].use(unit.position() if d[1] else unit))
    except Exception as e:
        trace("kit", f"cast_fail slot={d[0]} {type(e).__name__}")
        return False


def do_attack(w, s, unit):
    """Basic-attack unit if in range, then use the one cast per turn on whichever adds more: the damage
    spell on it, or an attack reset and a second basic attack (Vendetta, Varg, Ryth, Marcella).
    Returns True if anything was done. Never raises."""
    me = K["me"]
    if me is None:
        return False
    try:
        d_to = me.position().chebyshev_distance(unit.position())
    except Exception:
        return False
    done = False
    if d_to <= K["ar"]:
        done = _attack(me, unit)
    S = my_str()
    d = K["dmg"]
    spell = _dmg_of(_slot(d[0])) if d is not None and _dmg_castable() else 0.0
    reset = K["reset"] >= 0 and done and _ready(K["reset"]) and _alive(unit)
    if spell > 0 and (spell >= S or not reset):
        if _cast_dmg(me, unit, d):
            K["hit_r"] = -1
            return True
    if reset:
        try:
            if me.abilities()[K["reset"]].use(None):
                K["hit_r"] = -1
                _attack(me, unit)       # a kill may leave nothing to hit: refusal is fine
        except Exception as e:
            trace("kit", f"reset_fail {type(e).__name__}")
    return done


def _alive(unit):
    """unit is still visible with HP left (a reset on a dead target is wasted)."""
    try:
        return unit.is_visible() and unit.health() > 0
    except Exception:
        return False


def do_shield(w, s):
    """Cast my self-shield (Varg) when ready; True if cast."""
    i = K["shield"]
    if i < 0 or not _ready(i):
        return False
    try:
        ok = bool(K["me"].abilities()[i].use(None))
    except Exception as e:
        trace("kit", f"shield_fail {type(e).__name__}")
        return False
    if ok:
        K["hit_r"] = -1
    return ok


def clear_pred(live, strs):
    """Predicted clear of a group's live monsters live = [(camp, hp, Str)] by attackers of Strength strs:
    (rounds, total monster damage). rounds = ceil(live HP / sum(strs)); every live monster wakes on the first
    hit and hits one champion for its Strength each round after the first [measured A1/A3, ECONOMY.md].
    Pessimistic: monsters killed during the clear keep counting until the end."""
    tot = sum(strs)
    if tot <= 0:
        return (FAR, FAR)
    hp = sum(x for _, x, _ in live)
    if hp <= 0:
        return (0, 0.0)
    rounds = -int(-hp // tot)
    return (rounds, sum(st for _, _, st in live) * (rounds - 1))


def enemy_str(champ):
    """A visible enemy's live Strength, else its type's base Strength (50 if unknown)."""
    try:
        return float(champ.strength())
    except Exception:
        pass
    try:
        return float(CHAMP_BASE[int(champ.champion_name())][1])
    except Exception:
        return 50.0


def shop(w, s):
    """On spawn or while dead: buy my shard plan with all my gold (can_buy enforces where) [rules]."""
    me = K["me"] or cambc.me()
    kind = SHOP_PLAN.get(K["type"], IT.MONSTER_SHARD_OF_STRENGTH)
    try:
        n = int(me.gold_count()) // SHARD_GOLD
        if n <= 0:
            return False
        if me.can_buy(kind, n):
            me.buy(kind, n)
            trace("shop", f"n={n} kind={int(kind)}")
            return True
        b = 0
        while b < n and me.can_buy(kind):
            me.buy(kind, 1)
            b += 1
        if b:
            trace("shop", f"n={b} kind={int(kind)}")
        return b > 0
    except Exception as e:
        trace("kit", f"shop_fail {type(e).__name__}")
        return False

# ---- 50_rules.py ----
"""The rule list (docs/design/CORE.md): every turn, walk P["order"] top to bottom; the first rule that acts wins.

play(w, s, team) -> (tag, claim_h, rally). The tag starts with the rule's name (logs compare profiles by it).
No tasks, no stored intent. The only memory between turns: my claim (rewritten every turn), groups marked
unreachable for UNREACH_FOR rounds, the capture start per group, and the round an enemy was last seen.
Every threshold lives in a profile; rules read P["..."], never a module constant. PROFILE selects one.
"""
import cambc

PROFILE = "farm"

_FARM = {
    "order": ["DEAD", "CHANNEL", "FINISH", "KILL", "RECALL", "RETREAT", "RALLY", "BANK", "CAMP", "CAPTURE",
              "PICK", "STATION"],
    "KILL_MIN_GEMS": 10,     # a carrier: worth the detour (the bag dominates a kill's value, ECONOMY.md)
    "KILL_RATIO": 1.5,       # our Lanchester power must beat theirs by this near the target (P11)
    "KILL_REACH": 5,         # champions within this of the target count towards a fight's power
    "KILL_CHASE": 5,         # only a target this close is worth leaving the farm for (opportunistic, never a hunt)
    "KILL_HP_HITS": 2,       # a target this many of my hits from death is vulnerable whatever the odds (P8)
    "ESPAWN_R": 3,           # never chase onto the enemy's doorstep (they heal and shop there)
    "CHANNEL_R": 2,          # enemies this close can break a channel by killing me
    "RECALL_HP": 0.35,       # below this fraction of max HP: go home (recall heals in full [rules])
    "RECALL_SAFE": 8,        # recall only with no enemy this close (damage cancels it [rules])
    "FLEE_R": 6,             # enemies this close are weighed for a retreat
    "FLEE_RATIO": 1.3,       # retreat when their power beats ours by this
    "FLEE_HP": 0.6,          # ... and I am below this HP fraction (or carry CARRY_FEAR gems)
    "CARRY_FEAR": 20,        # a bag this big is not risked in a fair fight (P3)
    "RALLY_AGE": 6,          # a rally older than this is stale
    "RALLY_D": 12,           # join a rally within this (Chebyshev; no field to an arbitrary tile)
    "RALLY_D_CONTEST": 20,   # contested bank: one point in the middle, rally from further (CORE.md Modes)
    "RALLY_HP": 0.5,         # join a rally only above this HP fraction
    "BANK_AT": 40,           # bank a bag this big
    "BANK_AT_THREAT": 20,    # ... or this big when an enemy was seen within THREAT_MEMORY rounds
    "THREAT_MEMORY": 10,     # rounds an enemy sighting counts as a threat
    "END_BANK": 30,          # within this of the last round, bank any bag (unbanked gems score nothing)
    "LAST_ROUND": 2000,      # the game's last round [rules]
    "CONTEST_X": 1.3,        # contested bank test (20_world computes w.contested with its own copy)
    "CALM": 30,              # contested bank: bank alone only after this many rounds without an enemy
    "BANK_BUDDY": 4,         # contested bank: an ally this close makes banking safe
    "KEEP_HP": 0.4,          # each champion's share of a clear stops at this HP fraction: just above RECALL_HP,
                             # where rule RECALL pulls it out anyway (never die to a camp: gems destroyed)
    "BANK_FORCE_X": 2,       # contested bank: a bag this many times BANK_AT banks even without a buddy
    "MID_SLACK": 4,          # a group is on our half if d(spawn) <= d(espawn) + this
    "UNREACH_FOR": 40,       # rounds a group with a blocked approach is skipped
    "PAIR_WAIT": 25,         # rounds to wait for partners at a group I cannot clear alone before chipping it
    "PAIR_WAIT_ALONE": 8,    # ... when nobody has claimed it yet: long enough for an ally's next pick to see mine
    "CHIP_ROUNDS": 8,        # chip a group alone only if its full damage takes this many rounds to bring me to
                             # KEEP_HP: damaged camps never regenerate [measured A28], so a chip is progress,
                             # but against a big hitter (monolith) a trip is too short to be worth the walk
    "JOIN_W": 2.0,           # pick weight of a group that allies claimed but cannot clear without me (P10)
    "TEAM_R": 2,             # an ally within CAMP_R + this of a live monster counts as present for a clear
    "CAPTURE_GIVEUP": 8,     # rounds on a spawn tile with no reward before the capture counts as contested
    "GOLD_W": 0.2,           # gold's weight against gems in a pick's reward (gems win games)
    "PICK_CHECKS": 6,        # gstate() costs ~27k out of vision: check only this many best candidates
    "SHOP_GOLD": 30,         # one shard's price [rules]: shop on spawn at or above it
}
_AGGRO = dict(_FARM, KILL_MIN_GEMS=0, KILL_RATIO=1.1, KILL_REACH=8, KILL_CHASE=8, RALLY_D=20, CARRY_FEAR=40,
              order=["DEAD", "KILL", "CHANNEL", "FINISH", "RECALL", "RETREAT", "RALLY", "BANK", "CAMP",
                     "CAPTURE", "PICK", "STATION"])
PROFILES = {"farm": _FARM, "aggro": _AGGRO}
assert all(set(p) == set(_FARM) for p in PROFILES.values()), "profiles must share one key set"
P = PROFILES[PROFILE]

REWARD = {0: (22, 90), 1: (36, 160), 2: (24, 0), 3: (0, 35), 4: (200, 300)}   # CampType -> (gems, gold) [rules]
CAMP_R = 3                                                                     # every monster's range [measured A31]

_M = {"claim": None, "guess": None, "blk": None, "unreach": {}, "cap": {}, "seen": -9999, "went": -1, "rally": None,
      "pairwait": {}, "nokill": {}, "stuck": (None, 0), "norally": -1, "chase": (None, 0, 0)}
STUCK_ROUNDS = 40                 # the backstop: same tile this long outside a deliberate stand -> drop everything
                                  # (a last resort: every wait has its own shorter exit; the pair wait is 25+25)
STUCK_OK = ("DEAD", "CHANNEL", "RECALL", "CAPTURE", "STATION")   # deliberate stands (each has its own exit)


def _unstick(w, s, tag):
    """The no-freeze guarantee (CORE.md rule 1): release the claim and rest it, forget the chase or rally that
    held me here, so next turn's rule walk starts from nothing."""
    h = _M["claim"]
    if h is not None:
        _M["unreach"][h] = s.rnd + P["UNREACH_FOR"]
    _M["claim"] = None
    _M["pairwait"].clear()
    _M["cap"].clear()
    if tag.startswith("KILL c"):
        try:
            _M["nokill"][int(tag.split()[1][1:])] = s.rnd + 20
        except Exception:
            pass
    if tag.startswith("RALLY"):
        _M["norally"] = s.rnd + 20
    _say("stuck", f"{tag} g={h}")


def cur_claim():
    """My claim, for the snapshot's target group (w.snapshot(rnd, target=cur_claim()))."""
    return _M["claim"]


# ------------------------------------------------------------------ helpers
def _cheb(a, b):
    return max(abs(a.x - b.x), abs(a.y - b.y))


def _say(tag, text):
    t = globals().get("trace")
    if t is not None:
        t(tag, text)


def _cid(c):
    try:
        return int(c.champion_name())
    except Exception:
        return -1


def _channelling(c):
    try:
        return c.is_submitting_gems() or c.is_recalling()
    except Exception:
        return False


def _ally_str(c):
    try:
        return float(c.strength())
    except Exception:
        return enemy_str(c)


def _ally_max(c):
    try:
        return float(c.max_health())
    except Exception:
        return 1000.0


def _per(s):
    """My HP above KEEP_HP: what I can spend on a clear."""
    return s.hp - P["KEEP_HP"] * s.max_hp


def _team_at(w, s, live):
    """Strengths and HP pool (above KEEP_HP) of me plus the allies within CAMP_R + TEAM_R of a live monster:
    who is actually here to share the clear, not who claims it (P10). Monsters hit the nearest champion, so the
    damage lands on whoever is in front; the pool model lets that one recall and the rest finish [rules]."""
    tiles = [c.spawn_position() for c, _, _ in live]
    strs, pool = [my_str()], _per(s)
    for p, hp, g, c in s.allies:
        if min(_cheb(p, t) for t in tiles) <= CAMP_R + P["TEAM_R"]:
            strs.append(_ally_str(c))
            pool += hp - P["KEEP_HP"] * _ally_max(c)
    return strs, pool


def _need(w, s, live, cap):
    """(k, rounds): the fewest champions like me (sustained Strength, my HP) whose pooled HP above KEEP_HP covers
    the clear's damage; (None, rounds with cap champions) if even cap of us cannot."""
    S, per = my_str(), _per(s)
    rounds = FAR
    for k in range(1, max(1, cap) + 1):
        rounds, dmg = clear_pred(live, [S] * k)
        if dmg <= k * per:
            return k, rounds
    return None, rounds


def _chippable(s, live):
    """Alone, with an empty bag (a camp kill destroys carried gems [rules]), and the group's full damage leaves me
    CHIP_ROUNDS of attacks before KEEP_HP: hit it, recall at RECALL_HP, come back (no regen [measured A28])."""
    hit = sum(st for _, _, st in live)
    return s.bag == 0 and (hit <= 0 or _per(s) >= P["CHIP_ROUNDS"] * hit)


def power(w, s, center, r, mine):
    """Lanchester power, sum of hp * Str within r of center (P11). mine: our side (me always counted)."""
    if mine:
        tot = s.hp * my_hit(w, s)
        for p, hp, _, c in s.allies:
            if _cheb(p, center) <= r:
                tot += hp * _ally_str(c)
        return tot
    return sum(hp * enemy_str(c) for p, hp, _, c in s.enemies if _cheb(p, center) <= r)


def _live(w, s, h):
    """[(camp, hp, Str)] of live monsters of group h. Unread camps: last-known HP, except camps within
    CAMP_R of me that read None (in vision and not visible: dead)."""
    rows, camps = group_comp(w, h), w.camps.get(h, ())
    read = s.camp_hp.get(h)
    out = []
    for j, row in enumerate(rows):
        if j >= len(camps):
            break
        x = read[j] if read is not None and j < len(read) else None
        if x is None:
            if read is not None and _cheb(camps[j].spawn_position(), s.pos) <= CAMP_R:
                continue
            x = w.hp_known(camps[j], row[1], s.rnd)
        if x > 0:
            out.append((camps[j], x, row[2]))
    return out


def _hits(w, s, p):
    """An awake monster with Strength has tile p in range."""
    for cp, h in w.near(p, CAMP_R):
        if h not in s.awake:
            continue
        for k, mx, st, x, y in group_comp(w, h):
            if x == cp.x and y == cp.y and st > 0:
                return True
    return False


def _near_enemies(s, r, skip_channel=False):
    return [e for e in s.enemies if _cheb(e[0], s.pos) <= r and not (skip_channel and _channelling(e[3]))]


def _my_slot(w, s, team):
    for o in (s, w, team):
        v = getattr(o, "slot", None)
        if v is not None:
            return v
    return None


def _ally_claims(team, me):
    """{group: [slots]} claimed by live allies other than me."""
    out = {}
    if team is None:
        return out
    alive = getattr(team, "alive", None)
    for sl, h in (getattr(team, "claims", None) or {}).items():
        if h is None or sl == me or (alive is not None and sl not in alive):
            continue
        out.setdefault(h, []).append(sl)
    return out


def _team_n(team):
    """Live champions on my team, me included (the most a group take can count on)."""
    return max(1, len(getattr(team, "alive", None) or ()))


def _goto(w, key, rnd):
    _M["went"] = rnd
    return w.nav.goto(key, rnd)


def _bank_key(w, s=None):
    """The home altar on a contested map (bank together, CORE.md Modes); else the nearest altar by field
    (Chebyshev until its field exists, queued with w.want): a trip is dead time, the closest altar ends it."""
    b = w.bank_altar
    if b is None:
        return None
    if w.contested or s is None:
        return f"a{b}"
    best = None
    for i in range(len(w.altar_pos)):
        d = w.dist(f"a{i}", s.pos)
        if d is None:
            w.want(f"a{i}")
            d = _cheb(w.altar_pos[i], s.pos)
        if d < FAR and (best is None or d < best[0]):
            best = (d, i)
    return f"a{b}" if best is None else f"a{best[1]}"


# ------------------------------------------------------------------ rules
def rule_dead(w, s):
    if s.alive:
        return None
    shop(w, s)
    _M["claim"] = None
    return "DEAD"


def rule_channel(w, s):
    if not (s.submitting or s.recalling):
        return None
    try:
        left = int(w.me.remaining_channel_time())
    except Exception:
        left = 5
    burst = sum(enemy_str(c) for p, hp, g, c in _near_enemies(s, P["CHANNEL_R"]))
    if burst > 0 and s.hp <= burst * max(1, left):
        _cancel(w, s)
        return None
    return f"CHANNEL {'sub' if s.submitting else 'rec'} {left}"


def _cancel(w, s):
    try:
        if s.submitting:
            w.me.cancel_submit_gems()
        if s.recalling:
            w.me.cancel_recall()
    except Exception:
        pass
    s.submitting = s.recalling = False


def rule_finish(w, s):
    if not s.can_attack:
        return None
    hit, rng = my_hit(w, s), hit_range(w)
    for p, hp, g, c in sorted(s.enemies, key=lambda e: -e[2]):
        if _cheb(p, s.pos) <= rng and hp <= hit and do_attack(w, s, c):
            return f"FINISH c{_cid(c)}"
    return None


def rule_kill(w, s):
    hit, reach, best = my_hit(w, s), P["KILL_REACH"], None
    carrying = s.bag >= P["CARRY_FEAR"]          # P3: my own bag is not risked on anything but a finisher
    for p, hp, g, c in s.enemies:
        if g < P["KILL_MIN_GEMS"] or _M["nokill"].get(_cid(c), -1) > s.rnd:
            continue
        d = _cheb(p, s.pos)
        if d > P["KILL_CHASE"]:
            continue
        # Vulnerable = cannot get away: channelling (tribute/recall) or stunned, or already in my face. A running
        # target is a chase we lose to the farm (user rule: opportunistic kills only, never a hunt).
        if not (_channelling(c) or d <= hit_range(w) + 1):
            continue
        if carrying and hp > P["KILL_HP_HITS"] * hit:
            continue
        de = w.dist("espawn", p)
        if de is not None and de <= P["ESPAWN_R"]:
            continue
        weak = hp <= P["KILL_HP_HITS"] * hit
        if not weak and power(w, s, p, reach, True) < P["KILL_RATIO"] * power(w, s, p, reach, False):
            continue
        if _hits(w, s, p):
            continue
        if best is None or g > best[2]:
            best = (p, hp, g, c)
    if best is None:
        return None
    if s.submitting or s.recalling:
        _cancel(w, s)                  # aggro order puts KILL above CHANNEL: break the channel to fight
    p, c = best[0], best[3]
    cid, d = _cid(c), _cheb(p, s.pos)
    pc, pd, pn = _M["chase"]
    pn = pn + 1 if pc == cid and d >= pd else 0
    _M["chase"] = (cid, d, pn)
    if pn >= 3:                        # three rounds without closing: it is getting away, back to the farm
        _M["nokill"][cid] = s.rnd + 20
        _M["chase"] = (None, 0, 0)
        return None
    _M["rally"] = p
    if _cheb(p, s.pos) <= hit_range(w) and s.can_attack and do_attack(w, s, c):
        return f"KILL c{_cid(c)} at"
    if s.can_move and w.nav.greedy(p) == "moving":
        return f"KILL c{_cid(c)} mv"
    return f"KILL c{_cid(c)} wait"


def rule_recall(w, s, force=False):
    if s.hp >= P["RECALL_HP"] * s.max_hp and not force:
        return None
    if w.spawn.is_set(s.pos):
        if s.gold >= P["SHOP_GOLD"]:
            shop(w, s)
        return "RECALL heal"           # spawn heals at turn end [rules]: stay
    if _near_enemies(s, P["RECALL_SAFE"], True):
        return None
    if _hits(w, s, s.pos):             # a camp's hit cancels the recall [rules]: step out of its range first
        tiles = [(t, 0, 0, None) for t, h in w.near(s.pos, CAMP_R) if h in s.awake] or                 [(t, 0, 0, None) for t, h in w.near(s.pos, CAMP_R)]
        return _flee_step(w, s, tiles, hit_back=False).replace("RETREAT", "RECALL out")
    try:
        w.me.recall()
    except Exception:
        return None
    _M["claim"] = None
    return "RECALL"


def rule_retreat(w, s):
    near = _near_enemies(s, P["RECALL_SAFE"], True)
    if not near:
        return None
    low = s.hp < P["RECALL_HP"] * s.max_hp
    if not low:
        close = [e for e in near if _cheb(e[0], s.pos) <= P["FLEE_R"]]
        if not close or not (s.bag >= P["CARRY_FEAR"] or s.hp < P["FLEE_HP"] * s.max_hp):
            return None
        theirs = sum(hp * enemy_str(c) for p, hp, g, c in close)
        if theirs <= P["FLEE_RATIO"] * power(w, s, s.pos, P["FLEE_R"], True):
            return None
    return _flee_step(w, s, near)


def _flee_step(w, s, near, hit_back=True):
    """One step: max (distance to the nearest enemy, -d(spawn)); never onto blocked or camp tiles, never into
    an awake camp's range from outside it. No better tile: stand, and hit back if anything is in range."""
    def score(q):
        ds = w.dist("spawn", q)
        return (min(_cheb(e[0], q) for e in near), -(FAR if ds is None else ds))
    here = score(s.pos)
    cand = []
    if s.can_move and w.blocked is not None:
        in_range = _hits(w, s, s.pos)
        for dv in DIRS:
            q = s.pos + dv
            if not (0 <= q.x < w.W and 0 <= q.y < w.H) or w.blocked.is_set(q)                     or (not in_range and _hits(w, s, q)):     # off the map: is_set raises [measured]
                continue
            sc = score(q)
            if sc > here:
                cand.append((sc, q))
    for sc, q in sorted(cand, key=lambda t: t[0], reverse=True):
        if w.nav.move(q):
            return f"RETREAT mv d={sc[0]}"
    for p, hp, g, c in sorted(near, key=lambda e: _cheb(e[0], s.pos)) if hit_back else []:
        if _cheb(p, s.pos) <= hit_range(w) and s.can_attack and do_attack(w, s, c):
            return f"RETREAT hit c{_cid(c)}"
    return "RETREAT stand"


def rule_rally(w, s, team):
    r = getattr(team, "rally", None) if team is not None else None
    if not r or r[0] is None or r[1] > P["RALLY_AGE"] or _M["norally"] > s.rnd:
        return None
    rp = r[0]
    lim = P["RALLY_D_CONTEST"] if w.contested else P["RALLY_D"]
    d = _cheb(rp, s.pos)
    if d > lim or d <= 1 or s.hp < P["RALLY_HP"] * s.max_hp or s.bag >= P["CARRY_FEAR"]:
        return None
    if not s.can_move or w.nav.greedy(rp) != "moving":
        return None
    return f"RALLY d={d}"


def rule_bank(w, s):
    key, rnd = _bank_key(w, s), s.rnd
    if key is None or s.bag <= 0:
        return None
    end = rnd >= P["LAST_ROUND"] - P["END_BANK"]
    threat = rnd - _M["seen"] <= P["THREAT_MEMORY"]
    if not (end or s.bag >= P["BANK_AT"] or s.bag >= P["BANK_AT_THREAT"] and threat):
        return None
    if w.contested and not end and s.bag < P["BANK_FORCE_X"] * P["BANK_AT"]:
        buddy = any(_cheb(p, s.pos) <= P["BANK_BUDDY"] for p, hp, g, c in s.allies)
        if not buddy and rnd - _M["seen"] < P["CALM"]:
            return None
    d = w.dist(key, s.pos)
    if d is not None and d >= FAR:
        return None                    # bank altar unreachable on foot [measured A13]: keep farming
    _M["claim"] = None
    if d == 0:
        try:
            w.me.submit_gems(w.altar_pos[int(key[1:])])
            return f"BANK {key} ch"
        except Exception:
            return f"BANK {key} lock"  # refused (an enemy lock, or a channel already on)
    res = _goto(w, key, rnd)
    return f"BANK {key} {'mv' if res == 'moving' else res}"


def rule_camp(w, s, team):
    h = _M["claim"]
    if h is None:
        return None
    live = _live(w, s, h)
    if not live:
        return None
    near = min(_cheb(c.spawn_position(), s.pos) for c, _, _ in live)
    engaged = h in s.awake and near <= CAMP_R   # already in the fight: no regen, so stay till RECALL_HP [A28]
    if not engaged:
        if _M["guess"] == h and w.dist(f"g{h}", s.pos) is not None:
            _M["claim"] = _M["guess"] = None    # picked on a straight-line guess; the real walk is known now
            return None
        strs, pool = _team_at(w, s, live)
        k = _need(w, s, live, _team_n(team))[0]
        # Engage when the pooled HP covers the clear, or when as many of us are present as the need estimate
        # says (the pool model is pessimistic; RECALL pulls each body out at RECALL_HP, the camp keeps no regen).
        if clear_pred(live, strs)[1] > pool and (k is None or len(strs) < k):
            t = _camp_wait(w, s, team, h, live)
            if t != "CHIP":
                return t
    tgt = min(live, key=lambda t: _cheb(t[0].spawn_position(), s.pos))[0]
    tp = tgt.spawn_position()
    if _cheb(tp, s.pos) <= hit_range(w):
        if h in s.awake:
            do_shield(w, s)
        if s.can_attack and do_attack(w, s, tgt):
            return f"CAMP g{h} at"
        return f"CAMP g{h} wait"
    return _camp_walk(w, s, h, tp)


def _camp_wait(w, s, team, h, live):
    """Not enough of us here. Wait outside the group's range for partners (P10; free allies weigh it JOIN_W in
    PICK), for PAIR_WAIT rounds counted from my arrival (the walk is not waiting); then chip it alone if that is
    safe, else release it. Returns a tag, "CHIP", or None (released)."""
    coming = 1 + len(_ally_claims(team, _my_slot(w, s, team)).get(h, ()))
    k = _need(w, s, live, _team_n(team))[0]
    since, first = _M["pairwait"].get(h, (s.rnd, s.rnd))
    if coming > 1 and s.rnd - since > P["PAIR_WAIT"] - 10 and s.rnd - first <= 2 * P["PAIR_WAIT"]:
        since = s.rnd - (P["PAIR_WAIT"] - 10)              # a claimant is on its way: keep waiting (capped)
        _M["pairwait"][h] = (since, first)
    limit = P["PAIR_WAIT"] if coming > 1 else P["PAIR_WAIT_ALONE"]
    if k is not None and s.rnd - since <= limit:              # partners may still pick it (JOIN_W)
        if min(_cheb(c.spawn_position(), s.pos) for c, _, _ in live) > CAMP_R + P["TEAM_R"]:
            res = _goto(w, f"g{h}", s.rnd)
            return f"CAMP g{h} pair:{res}"
        _M["pairwait"].setdefault(h, (s.rnd, s.rnd))
        if _hits(w, s, s.pos):
            return _flee_step(w, s, [(t, 0, 0, None) for t, g in w.near(s.pos, CAMP_R)], hit_back=False)                 .replace("RETREAT", f"CAMP g{h} pairwait")
        return f"CAMP g{h} pairwait {coming}/{k}"
    if _chippable(s, live):
        return "CHIP"
    _M["pairwait"].pop(h, None)
    _M["unreach"][h] = s.rnd + P["UNREACH_FOR"]
    _M["claim"] = None
    _say("claim", f"release g{h} k={k} coming={coming}")
    return None


def _camp_walk(w, s, h, tp):
    """Walk into attack range of tp. The field's goal is next to ANY camp of the group, so after a kill I can be
    "here" yet out of reach of the next monster: step towards it (sideways too, allies crowd the group). Only a
    blocked approach for GIVE_UP_ROUNDS rests the group (a wait while allies move is not a blocked approach)."""
    res = _goto(w, f"g{h}", s.rnd)
    if res == "moving":
        _M["blk"] = None
        return f"CAMP g{h} mv"
    if res == "here" and s.can_move and w.nav.greedy(tp, sideways=True) == "moving":
        _M["blk"] = None
        return f"CAMP g{h} mv:in"
    if res != "stuck":
        b = _M["blk"]
        if b is None or b[0] != h:
            _M["blk"] = b = (h, s.rnd)
        if s.rnd - b[1] < GIVE_UP_ROUNDS:
            return f"CAMP g{h} wait"
    _M["blk"] = None
    _M["unreach"][h] = s.rnd + P["UNREACH_FOR"]
    _M["claim"] = None
    _say("claim", f"unreach g{h} {res}")
    return None


def rule_capture(w, s):
    h = _M["claim"]
    if h is None:
        return None
    st = w.gstate(h)
    if st != "dead":
        if st in ("alive", "respawning"):
            _M["cap"].pop(h, None)
        return None
    tiles = [V(x, y) for k, mx, st, x, y in group_comp(w, h)]
    if any(t == s.pos for t in tiles):
        since, bag, gold = _M["cap"].setdefault(h, (s.rnd, s.bag, s.gold))
        if s.rnd - since >= P["CAPTURE_GIVEUP"] and s.bag == bag and s.gold == gold:
            _M["cap"].pop(h, None)
            _M["unreach"][h] = s.rnd + P["UNREACH_FOR"]
            _M["claim"] = None
            return None                # contested: someone else holds it; pick again
        return f"CAPTURE g{h} at {s.rnd - since}"
    _M["cap"].pop(h, None)
    if any(p == t for p, _, _, _ in s.allies for t in tiles):
        _M["claim"] = None             # an ally already holds a spawn tile: a second one only splits the reward
        return None                    # and speeds nothing [rules, Camps & capture]: go do something else
    if s.can_move:
        for t in sorted(tiles, key=lambda t: _cheb(t, s.pos)):
            if _cheb(t, s.pos) == 1 and w.nav.move(t):
                return f"CAPTURE g{h} on"
    res = _goto(w, f"g{h}", s.rnd)
    return f"CAPTURE g{h} {'mv' if res == 'moving' else res}"


def _on_our_half(w, h):
    """d(spawn) <= d(espawn) + MID_SLACK, measured at the group's anchor (Chebyshev: camp tiles are walls
    of every field, and a per-group field read at 60 groups would cost ~0.3M a pick)."""
    a = w.anchor.get(h)
    sp, ep = w.anchor.get("spawn"), w.anchor.get("espawn")
    if a is None or sp is None or ep is None:
        return True
    return _cheb(a, sp) <= _cheb(a, ep) + P["MID_SLACK"]


def _pick_cands(w, s, claims, n):
    """Groups on our half, not resting, with room for me, as (score, h, guessed walk), best first.
    score = reward per champion-round: (gems + GOLD_W * gold) / k / (walk + clear rounds + 1), with k the
    champions the clear needs (or n for a chip). A group accepts max(2, k) claimants (a pair speeds any clear;
    more only when the clear needs them); a group that allies claimed but cannot clear without me weighs JOIN_W."""
    cands = []
    for h in w.camps:
        if _M["unreach"].get(h, -1) > s.rnd or not _on_our_half(w, h):
            continue
        walk, guess = w.dist(f"g{h}", s.pos), False
        if walk is None:
            w.want(f"g{h}")
            walk, guess = _cheb(w.anchor[h], s.pos), True
        if walk >= FAR:
            continue
        live = _live(w, s, h)
        k, rounds = _need(w, s, live, n)
        if k is None:
            if not _chippable(s, live):
                continue
            k = n
        c = len(claims.get(h, ()))
        if c >= max(2, k):
            continue
        rw = sum(REWARD.get(r[0], (0, 0))[0] + P["GOLD_W"] * REWARD.get(r[0], (0, 0))[1] for r in group_comp(w, h))
        sc = rw / k / (walk + rounds + 1) * (P["JOIN_W"] if 0 < c < k else 1)
        cands.append((sc, h, guess))
    cands.sort(key=lambda t: -t[0])
    return cands


def rule_pick(w, s, team):
    claims = _ally_claims(team, _my_slot(w, s, team))
    pick = None
    for sc, h, guess in _pick_cands(w, s, claims, _team_n(team))[:P["PICK_CHECKS"]]:
        score = sc
        st = w.gstate(h)
        if st == "respawning" or st == "dead" and claims.get(h):
            continue                   # a capture needs one champion: an ally already holds it [rules]
        pick = h
        _M["guess"] = h if guess else None
        break
    if pick is None:
        return None
    if _M["claim"] != pick:
        _M["pairwait"].clear()
        d = w.dist(f"g{pick}", s.pos)
        _say("claim", f"g{pick} walk={d} score={score:.3f} guess={int(_M['guess'] is not None)}")
    _M["claim"] = pick
    if _M["went"] == s.rnd:
        return f"PICK g{pick} claim"   # the field walk was already asked for this turn (one goto per turn)
    res = _goto(w, f"g{pick}", s.rnd)
    return f"PICK g{pick} {'mv' if res == 'moving' else res}"


def rule_station(w, s):
    """Nothing to pick. Idle time is free healing and shopping: recall when hurt or holding a shard's gold
    (spawn heals in full and sells [rules]; a recall also re-runs PICK at full HP, which lowers every group's
    need); else walk to the bank altar's ring."""
    key = _bank_key(w)
    _M["claim"] = None
    if not w.spawn.is_set(s.pos) and (s.hp < s.max_hp or s.gold >= P["SHOP_GOLD"]):
        t = rule_recall(w, s, force=True)
        if t:
            return "STATION " + t
    if key is None or _M["went"] == s.rnd:
        return "STATION idle"
    res = _goto(w, key, s.rnd)
    return f"STATION {key} {'mv' if res == 'moving' else res}"


RULES = {"DEAD": rule_dead, "CHANNEL": rule_channel, "FINISH": rule_finish, "KILL": rule_kill,
         "RECALL": rule_recall, "RETREAT": rule_retreat, "RALLY": rule_rally, "BANK": rule_bank,
         "CAMP": rule_camp, "CAPTURE": rule_capture, "PICK": rule_pick, "STATION": rule_station}
_TEAM_ARG = ("RALLY", "CAMP", "PICK")


def play(w, s, team):
    """Walk P["order"]; the first rule returning a tag acted. Returns (tag, claim_h, rally)."""
    _M["rally"] = None
    if s.enemies:
        _M["seen"] = s.rnd
    if s.alive and s.gold >= P["SHOP_GOLD"] and w.spawn.is_set(s.pos):
        try:
            shop(w, s)                 # free action on spawn [rules]
        except Exception:
            pass
    tag = "IDLE"
    for name in P["order"]:
        fn = RULES[name]
        try:
            t = fn(w, s, team) if name in _TEAM_ARG else fn(w, s)
        except Exception as e:
            et = globals().get("err_text")
            _say("err", et(e) if et else f"err:{name}:{type(e).__name__}")
            continue
        if t:
            tag = t
            break
        if name == "CHANNEL" and (s.submitting or s.recalling):
            break                      # still channelling (nothing else can act until it ends)
    last, n = _M["stuck"]
    n = n + 1 if last == s.pos and not tag.startswith(STUCK_OK) and not tag.endswith(" at") else 0
    _M["stuck"] = (s.pos, n)
    if n >= STUCK_ROUNDS:
        _M["stuck"] = (s.pos, 0)
        _unstick(w, s, tag)
    rally = _M["rally"] if tag.startswith("KILL") else None
    return tag, _M["claim"], rally

# ---- 60_team.py ----
"""The 8 shared bytes (docs/design/CORE.md -> Shared memory). Read once at turn start, written once at turn end.

Bytes 0-4, one per draft slot: bit 7 heartbeat (toggles every turn while alive), bits 0-6 claimed group handle + 1
(0 = none). A slot whose heartbeat did not change for HB_DEAD rounds is dead: its claim is ignored.
Bytes 5-6: RALLY x, y. Byte 7: (round mod 255) + 1 when written (0 = none).
Slot = index of my ChampionType in the fixed pick order (90_main picks in that order; the enemy holding a
champion does not block our pick [rules], so it only differs after a missed pick: such a champion takes slot 4).
"""

SLOT_TYPES = (0, 2, 10, 7, 5)   # ChampionType RYTH, VENDETTA, VARG, MARCELLA, STELLAR = pick order [sdk]
HB_DEAD = 2                     # heartbeat unchanged this many rounds -> slot dead
_TBUF = bytearray(8)


class TeamMem:
    """This turn's view of the shared bytes."""
    __slots__ = ("slot", "claims", "alive", "rally", "mine")


class _HB:                      # reader state: last heartbeat bit per slot, round it last changed
    bit = [None] * 5
    changed = [0] * 5
    me = None


def my_slot(w):
    if _HB.me is None:
        _HB.me = SLOT_TYPES.index(w.ctype) if w.ctype in SLOT_TYPES else 4
    return _HB.me


def team_read(w, s):
    """claims {slot: group handle} of other live slots, alive {slots incl. me if alive}, rally (Vec2, age) or None,
    mine = my own claim as last written (or None)."""
    t = TeamMem()
    t.slot = me = my_slot(w)
    t.claims, t.alive, t.rally, t.mine = {}, set(), None, None
    try:
        cambc.shared_memory.read(0, _TBUF)
    except Exception:
        return t
    rnd = s.rnd
    for j in range(5):
        b = _TBUF[j]
        hb = b >> 7
        if _HB.bit[j] is None:              # first read: alive only once it toggles (unused slots stay 0)
            _HB.bit[j], _HB.changed[j] = hb, -100
        elif hb != _HB.bit[j]:
            _HB.bit[j], _HB.changed[j] = hb, rnd
        c = (b & 127) - 1
        if j == me:
            t.mine = c if c >= 0 else None
            if s.alive:
                t.alive.add(j)
        elif rnd - _HB.changed[j] <= HB_DEAD:
            t.alive.add(j)
            if c >= 0:
                t.claims[j] = c
    r7 = _TBUF[7]
    if r7:
        t.rally = (V(_TBUF[5], _TBUF[6]), (rnd % 255 + 1 - r7) % 255)
    return t


def team_write(w, s, claim_h, rally_pos):
    """My slot byte (heartbeat toggled while alive; 0 when dead) and, when given, the RALLY tile and round."""
    me = my_slot(w)
    if s.alive:
        hb = (_TBUF[me] >> 7) ^ 1
        c = claim_h + 1 if isinstance(claim_h, int) and 0 <= claim_h < 127 else 0
        b = hb << 7 | c
    else:
        b = 0
    _TBUF[me] = b
    try:
        cambc.shared_memory.write(me, bytes([b]))
        if rally_pos is not None:
            cambc.shared_memory.write(5, bytes([rally_pos.x & 255, rally_pos.y & 255, s.rnd % 255 + 1]))
    except Exception:
        pass

# ---- 90_main.py ----
"""Entry: `if cambc.is_draft(): draft_main() else: play_main()` (docs/design/CORE.md).

Draft: pick FIRST on every draft turn (a missed pick is random [rules]); nothing is written to draft memory
(draft_memory.submit() raises Error 18 once pick() was called in the same turn [measured, tzu 40_draft]).
Play, per round: fuel start -> w.snapshot -> team_read -> play() (50_rules; kit_init once) -> team_write ->
w.work() background fields under the fuel guard -> one trace line
    P|r|T|id|t|<tag> x,y hp=.. bag=.. gold=.. fuel=.. [bg=jobs/fuel]
A turn that raises traces err:<line>:<type>:<msg> as its tag and still writes the team bytes (heartbeat).
"""

if cambc.is_draft():
    # ChampionDraft values [sdk]: RYTH 0, VENDETTA 2, VARG 9, MARCELLA 6, STELLAR 4; then any other as backup,
    # so the pick is never None (pick(None) raises). The enemy holding a champion does not block it [rules].
    PICKS = (0, 2, 9, 6, 4)
    BACKUP = PICKS + tuple(d for d in range(11) if d not in PICKS)

    def draft_main():
        try:
            _TAG[0] = f"{'AB'[cambc._bc.my_team()]}|draft"
        except Exception:
            pass
        while True:
            try:
                ours = [int(p) for p in cambc.draft.current_draft(Team.ALLY)]
                p = next((d for d in BACKUP if d not in ours), PICKS[0])
                cambc.draft.pick(p)                    # FIRST, before anything else this turn
                trace("draft", f"picked={p} ours={ours}")
            except Exception as e:
                trace("draft", err_text(e))
            cambc.end_turn()

    draft_main()
else:
    def play_main():
        base_init()
        trace("boot", f"f={fuel()} type={int(cambc.me().champion_name())}")
        w = nav = None
        kit_done = False
        claim = rally = None           # last claim (also the snapshot's target group) and this turn's rally
        while True:
            FUEL.start()
            rnd = cambc.round_number()
            tag, rally, jobs, bgf = "boot", None, 0, 0
            try:
                if w is None:
                    w = World()
                    nav = w.nav = Nav(w)
                s = w.snapshot(rnd, claim)
                team = team_read(w, s)
                if not w.ready and w.setup():
                    s = w.snapshot(rnd, claim)                     # camp table ready: near groups now known
                    trace("world", f"groups={len(w.groups)} altars={len(w.altar_pos)} map={w.W}x{w.H} "
                                   f"bank=a{w.bank_altar} contested={int(w.contested)} fuel={FUEL.used()}")
                if w.ready:
                    if not kit_done:
                        kit_done = True
                        kit_init(w, s)
                    tag, claim, rally = play(w, s, team)
            except Exception as e:
                tag = err_text(e)
            try:
                if w is not None and w.snap is not None:
                    team_write(w, w.snap, claim, rally)            # every turn, crashed ones too
            except Exception as e:
                tag += " w" + err_text(e)
            try:
                if w is not None and w.ready:
                    jobs, bgf = w.work()                            # background fields under the reserve
            except Exception as e:
                tag += " b" + err_text(e)
            try:
                s = w.snap if w is not None else None
                if s is not None:
                    p = nav.dest if nav.moved_round == rnd else s.pos
                    bg = f" bg={jobs}/{bgf}" if jobs else ""
                    cl = ",".join(f"{k}:{v}" for k, v in sorted(team.claims.items())) if team else "-"
                    trace("t", f"{tag} {p.x},{p.y} hp={int(s.hp)} bag={s.bag} gold={s.gold} "
                               f"fuel={FUEL.used()} cl={cl}{bg}")
                else:
                    trace("t", f"{tag} fuel={FUEL.used()}")
            except Exception as e:
                trace("t", f"{err_text(e)} fuel={FUEL.used()}")
            cambc.end_turn()

    play_main()
